CREATE TABLE `amis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id_1` int NOT NULL,
  `user_id_2` int NOT NULL,
  `status` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_amis` (`user_id_1`,`user_id_2`),
  UNIQUE KEY `uq_amis_pair` ((least(`user_id_1`,`user_id_2`)),(greatest(`user_id_1`,`user_id_2`))),
  KEY `fk_amis_user2` (`user_id_2`),
  CONSTRAINT `fk_amis_user1` FOREIGN KEY (`user_id_1`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_amis_user2` FOREIGN KEY (`user_id_2`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `amis_chk_1` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'accepted',_utf8mb4'rejected')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

