CREATE TABLE `announcements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sport_type` varchar(50) NOT NULL,
  `slot_id` bigint unsigned DEFAULT NULL,
  `terrain_id` bigint unsigned DEFAULT NULL,
  `slot_start` timestamp NOT NULL,
  `slot_end` timestamp NOT NULL,
  `places_total` int NOT NULL,
  `places_disponibles` int NOT NULL,
  `description` text,
  `manual_address` varchar(500) DEFAULT NULL,
  `manual_city` varchar(100) DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `status` enum('active','expired','cancelled','validated') DEFAULT 'active',
  `reservation_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `visibility` varchar(10) DEFAULT 'public',
  `public_place_id` varchar(50) DEFAULT NULL COMMENT 'Identifiant équipement data.gouv.fr (equip_numero) pour les lieux publics',
  `expiration_date` timestamp NULL DEFAULT NULL COMMENT 'Date limite d''inscription (par défaut 24h avant slot_start)',
  `auto_cancel` tinyint(1) DEFAULT '1' COMMENT 'Annuler automatiquement si pas assez de participants avant expiration',
  `min_participants` int DEFAULT '2' COMMENT 'Nombre minimum de participants requis pour ne pas annuler',
  `lat` decimal(10,8) DEFAULT NULL,
  `lng` decimal(11,8) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_announcements_reservation_id` (`reservation_id`),
  KEY `idx_announcements_slot_id` (`slot_id`),
  KEY `idx_announcements_status` (`status`),
  KEY `idx_announcements_public_place_id` (`public_place_id`),
  KEY `idx_expiration_status` (`expiration_date`,`status`),
  KEY `idx_slot_start_status` (`slot_start`,`status`),
  KEY `fk_announcements_terrain` (`terrain_id`),
  KEY `fk_announcements_creator` (`created_by`),
  CONSTRAINT `fk_announcements_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_announcements_reservation_id` FOREIGN KEY (`reservation_id`) REFERENCES `reservations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_announcements_slot_id` FOREIGN KEY (`slot_id`) REFERENCES `slots` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_announcements_terrain` FOREIGN KEY (`terrain_id`) REFERENCES `terrains` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

